import "server-only";
import { randomBytes } from "node:crypto";
import { and, asc, eq, isNull, or } from "drizzle-orm";
import { db, schema as s } from "@/db";
import { createBooking, createHold, publishCalendar } from "./booking";
import { enqueue } from "./outbox";
import { redis } from "./redis";

/** How long a client has to accept a freed slot before it moves down the queue. */
export const OFFER_TTL_SEC = 15 * 60;

export type JoinResult = { entryId: string };

export async function joinWaitlist(opts: {
  businessId: string;
  serviceId: string;
  staffId?: string | null;
  dateISO: string;
  client: { name: string; phone: string };
}): Promise<JoinResult> {
  const { businessId, serviceId, staffId, dateISO, client } = opts;

  return db.transaction(async (tx) => {
    const [existing] = await tx
      .select()
      .from(s.clients)
      .where(and(eq(s.clients.businessId, businessId), eq(s.clients.phone, client.phone)));
    const clientRow =
      existing ??
      (
        await tx
          .insert(s.clients)
          .values({ businessId, name: client.name, phone: client.phone })
          .returning()
      )[0];

    const [entry] = await tx
      .insert(s.waitlistEntries)
      .values({
        businessId,
        serviceId,
        staffId: staffId ?? null,
        clientId: clientRow.id,
        dateISO,
      })
      .returning();

    return { entryId: entry.id };
  });
}

type FreedSlot = { staffId: string; serviceId: string; startMs: number; endMs: number };

/**
 * Offers a freed slot to the longest-waiting eligible client.
 *
 * Eligibility: same service, same local day, and either no master preference
 * or a preference for the one who freed up. Returns the entry that was offered,
 * or null when nobody is waiting (the slot simply returns to public stock).
 */
----
}

// ---------- Booking creation ----------

export type BookResult =
  | { ok: true; bookingId: string }
  | { ok: false; error: "hold_expired" | "slot_taken" };

export async function createBooking(opts: {
  businessId: string;
  staffId: string;
  serviceId: string;
  slot: Range;
  holdToken: string;
  client: { name: string; phone: string };
}): Promise<BookResult> {
  const { businessId, staffId, serviceId, slot, holdToken, client } = opts;

  // The hold must still be alive and belong to this caller.
  const raw = await redis().get(holdKey(staffId, slot.startMs));
  if (!raw || (JSON.parse(raw) as Hold).token !== holdToken) {
    return { ok: false, error: "hold_expired" };
  }

  const [service] = await db
    .select()
    .from(s.services)
    .where(and(eq(s.services.id, serviceId), eq(s.services.businessId, businessId)));
  if (!service) return { ok: false, error: "slot_taken" };

  // Upsert client by (business, phone)
  const [existing] = await db
    .select()
    .from(s.clients)
    .where(and(eq(s.clients.businessId, businessId), eq(s.clients.phone, client.phone)));
  const clientRow =
    existing ??
    (await db
      .insert(s.clients)
      .values({ businessId, name: client.name, phone: client.phone })
      .returning())[0];

  try {
    // Booking, audit trail and outbound messages commit together: a client can
    // never end up with a confirmation for a booking that was rolled back.
    const bookingId = await db.transaction(async (tx) => {
      const [booking] = await tx
        .insert(s.bookings)
        .values({
          businessId,
          staffId,
          serviceId,
          clientId: clientRow.id,
          startAt: new Date(slot.startMs),
          endAt: new Date(slot.endMs),
          status: "confirmed",
          priceKzt: service.priceKzt,
        })
        .returning();

      await tx.insert(s.auditLog).values({
        businessId,
        action: "booking.create",
        entity: "booking",
        entityId: booking.id,
        meta: { staffId, serviceId, startAt: new Date(slot.startMs).toISOString() },
      });

      await enqueue(tx, {
        businessId,
        topic: "booking.confirmed",
        payload: { bookingId: booking.id },
        dedupeKey: `booking.confirmed:${booking.id}`,
      });

      // Reminder the day before; retired automatically if the booking is
      // cancelled before the worker gets to it.
