import { describe, expect, it } from "vitest";
import { normalizePhone, phoneSchema } from "./phone";

describe("phoneSchema", () => {
  it.each([
    "+77015551234",
    "+7 701 555 12 34",
    "+7 (701) 555-12-34",
    "+7-701-555-12-34",
    "+7.701.555.12.34",
    "77015551234",
    " +7 701 555 12 34 ",
  ])("accepts %j as +77015551234", (input) => {
    expect(phoneSchema.parse(input)).toBe("+77015551234");
  });

  it.each(["call me", "+7 701", "+7 701 555 12 3x", "", "+7 (701) 555-12-34-99999999"])(
    "rejects %j",
    (input) => {
      expect(phoneSchema.safeParse(input).success).toBe(false);
    },
  );
});

describe("normalizePhone", () => {
  it("strips formatting and keeps the leading plus", () => {
    expect(normalizePhone("+7 (701) 555-12-34")).toBe("+77015551234");
  });
});

